<script lang="ts">
  import { markdownBlocks, inlineMarkdown } from '$lib/updater/markdown';
  let { text, onOpenExternal }: { text: string; onOpenExternal?: (url: string) => void } = $props();
  const blocks = $derived(markdownBlocks(text));
</script>
{#snippet inline(text: string)}{#each inlineMarkdown(text) as token}{#if token.kind === 'link'}<a href={token.url} target="_blank" rel="noopener noreferrer" onclick={onOpenExternal ? (event) => { event.preventDefault(); onOpenExternal?.(token.url!); } : undefined}>{token.text}</a>{:else if token.kind === 'strong'}<strong>{token.text}</strong>{:else if token.kind === 'emphasis'}<em>{token.text}</em>{:else if token.kind === 'code'}<code>{token.text}</code>{:else}{token.text}{/if}{/each}{/snippet}
<div class="release-notes">{#each blocks as block}{#if block.kind === 'heading'}<svelte:element this={`h${block.level}`}>{@render inline(block.text)}</svelte:element>{:else if block.kind === 'code'}<pre><code>{block.text}</code></pre>{:else if block.kind === 'quote'}<blockquote>{@render inline(block.text)}</blockquote>{:else if block.kind === 'list'}{#if block.ordered}<ol>{#each block.items ?? [] as item}<li>{@render inline(item)}</li>{/each}</ol>{:else}<ul>{#each block.items ?? [] as item}<li>{@render inline(item)}</li>{/each}</ul>{/if}{:else}<p>{@render inline(block.text)}</p>{/if}{/each}</div>
<style>.release-notes { white-space: normal; overflow-wrap: anywhere; line-height: 1.65; } .release-notes :global(h1),.release-notes :global(h2),.release-notes :global(h3) { margin: 16px 0 8px; line-height: 1.3; } p { white-space: pre-wrap; margin: 8px 0; } pre { overflow-x: auto; padding: 10px; background: #ffffff09; } code { font-size: .9em; } a { color: #d99b9f; } a:focus-visible { outline: 2px solid white; outline-offset: 3px; } blockquote { margin-left: 0; padding-left: 14px; border-left: 3px solid #ffffff30; }</style>
